# Replays the Kaplan-Meier fixtures in fixtures/r/, generated by scripts/regenerate_r_fixtures.R.
# The Python suite replays the same fixtures (python/tests/test_r_parity.py). The datasets come
# from the survival package, which is only needed for these tests.

TOL <- 1e-9

# Compare one curve with a fixture block written by km_one() in the generator.
expect_km_matches <- function(curve, expected, label) {
  expect_equal(curve$time, r_numbers(expected$time), tolerance = TOL, label = paste(label, "time"))
  expect_equal(curve$estimate, r_numbers(expected$surv), tolerance = TOL, label = paste(label, "surv"))
  expect_equal(curve$std_error, r_numbers(expected$se), tolerance = TOL, label = paste(label, "se"))
}

expect_limits_match <- function(fit, expected, suffix, label) {
  curve <- as.data.frame(fit)
  expect_equal(
    curve$conf_low,
    r_numbers(expected[[paste0("lower_", suffix)]]),
    tolerance = TOL,
    label = paste(label, "lower", suffix)
  )
  expect_equal(
    curve$conf_high,
    r_numbers(expected[[paste0("upper_", suffix)]]),
    tolerance = TOL,
    label = paste(label, "upper", suffix)
  )
}

test_that("the overall curve on lung matches the fixture", {
  skip_if_no_shared_cases()
  skip_if_not_installed("survival")
  expected <- read_fixture("km_lung_overall")$overall
  lung <- survival::lung

  fit <- kaplan_meier(Surv(time, status) ~ 1, data = lung)
  expect_km_matches(as.data.frame(fit), expected, "lung")
  expect_limits_match(fit, expected, "log", "lung")
  expect_limits_match(
    kaplan_meier(Surv(time, status) ~ 1, data = lung, conf_type = "plain"),
    expected,
    "plain",
    "lung"
  )
  expect_limits_match(
    kaplan_meier(Surv(time, status) ~ 1, data = lung, conf_type = "log-log"),
    expected,
    "loglog",
    "lung"
  )

  med <- median(fit)
  expect_equal(med$time, expected$median)
  expect_equal(med$conf_low, expected$median_lower)
  expect_equal(med$conf_high, expected$median_upper)
})

test_that("curves by sex on lung match the fixture", {
  skip_if_no_shared_cases()
  skip_if_not_installed("survival")
  expected <- read_fixture("km_lung_by_sex")
  fit <- kaplan_meier(Surv(time, status) ~ sex, data = survival::lung)

  expect_identical(fit$groups$sex, c(1, 2))
  curves <- as.data.frame(fit)
  med <- median(fit)
  for (sex in names(expected)) {
    rows <- curves[curves$sex == as.numeric(sex), ]
    expect_km_matches(rows, expected[[sex]], paste("sex", sex))
    expect_equal(rows$conf_low, r_numbers(expected[[sex]]$lower_log), tolerance = TOL)
    expect_equal(rows$conf_high, r_numbers(expected[[sex]]$upper_log), tolerance = TOL)
    expect_equal(med$time[med$sex == as.numeric(sex)], expected[[sex]]$median)
  }
})

