# -- behaviour ------------------------------------------------------------------------------------

# The direct definition of the infinitesimal-jackknife standard error, building the full
# subjects-by-times influence matrix. kaplan_meier() uses an equivalent O(n log n) form.
robust_sigma_reference <- function(start, stop, event, w, cluster = NULL) {
  time <- sort(unique(stop))
  at_risk <- outer(start, time, `<`) & outer(stop, time, `>=`)
  event_here <- outer(stop, time, `==`) & (event == 1)
  n_risk <- colSums(w * at_risk)
  n_event <- colSums(w * event_here)
  hazard <- n_event / n_risk
  scale <- ifelse(n_risk - n_event > 0, 1 / (n_risk - n_event), 0)
  increments <- w * (event_here - sweep(at_risk, 2L, hazard, `*`))
  influence <- -t(apply(sweep(increments, 2L, scale, `*`), 1L, cumsum))
  if (!is.null(cluster)) {
    influence <- rowsum(influence, cluster)
  }
  sqrt(colSums(influence^2))
}

test_that("robust variance agrees with its direct definition", {
  set.seed(42)
  for (trial in 1:20) {
    n <- sample(5:60, 1)
    # Rounded times give ties, and some subjects enter late.
    start <- round(runif(n, 0, 3))
    stop <- start + round(rexp(n, 0.3)) + 1
    event <- rbinom(n, 1, 0.6)
    w <- if (trial %% 2 == 0) runif(n, 0.2, 3) else rep(1, n)
    cluster <- if (trial %% 3 == 0) sample(1:6, n, replace = TRUE) else NULL
    d <- data.frame(start, stop, event, w, cluster = if (is.null(cluster)) seq_len(n) else cluster)

    fit <- if (is.null(cluster)) {
      kaplan_meier(Surv(start, stop, event) ~ 1, data = d, weights = w, robust = TRUE)
    } else {
      kaplan_meier(Surv(start, stop, event) ~ 1, data = d, weights = w, cluster = cluster)
    }
    curve <- as.data.frame(fit)
    sigma <- robust_sigma_reference(start, stop, event, w, cluster)
    expect_equal(curve$std_error, curve$estimate * sigma, tolerance = 1e-10, label = paste("trial", trial))
  }
})

test_that("robust variance handles a single time and counting-process data", {
  one <- kaplan_meier(Surv(time, status) ~ 1, data = small[1, ], robust = TRUE)
  expect_identical(nrow(as.data.frame(one)), 1L)
  trunc <- data.frame(start = c(0, 2, 1, 3), stop = c(5, 6, 4, 8), event = c(1, 0, 1, 1))
  fit <- kaplan_meier(Surv(start, stop, event) ~ 1, data = trunc, robust = TRUE)
  expect_true(all(is.finite(as.data.frame(fit)$std_error[1:2])))
})

test_that("integer weights match replicated rows", {
  w <- c(2, 1, 3, 1, 1, 2, 1, 1, 2, 1)
  weighted <- kaplan_meier(Surv(time, status) ~ 1, data = small, weights = w)
  replicated <- kaplan_meier(Surv(time, status) ~ 1, data = small[rep(seq_along(w), w), ])
  expect_equal(as.data.frame(weighted), as.data.frame(replicated))
})

test_that("weights and subset are evaluated in data", {
  small$w <- 2
  by_name <- kaplan_meier(Surv(time, status) ~ 1, data = small, weights = w, subset = sex == 1)
  expect_identical(as.data.frame(by_name)$n_risk[1], 10)
})

test_that("rows with missing values are dropped and counted", {
  gappy <- small
  gappy$time[2] <- NA
  gappy$sex[3] <- NA
  fit <- kaplan_meier(Surv(time, status) ~ sex, data = gappy)
  expect_identical(fit$n_dropped, 2L)
  expect_identical(sum(vapply(fit$curves, function(curve) curve$n_risk[1], numeric(1))), 8)
})

test_that("several grouping variables give one curve per combination", {
  fit <- kaplan_meier(Surv(time, status) ~ sex + ecog, data = small)
  expect_identical(nrow(fit$groups), 4L)
  expect_named(as.data.frame(fit), c(
    "strata", "sex", "ecog", "time", "n_risk", "n_event", "n_censor",
    "estimate", "std_error", "conf_low", "conf_high"
  ))
  expect_named(median(fit), c("strata", "sex", "ecog", "time", "conf_low", "conf_high"))
  expect_identical(median(fit)$strata, c("sex=1, ecog=0", "sex=1, ecog=1", "sex=2, ecog=0", "sex=2, ecog=1"))
})

test_that("one curve and several curves give the same layout", {
  one <- kaplan_meier(Surv(time, status) ~ 1, data = small)
  two <- kaplan_meier(Surv(time, status) ~ sex, data = small)

  # Only the formula's grouping variables differ, never the presence or type of anything else.
  without_groups <- function(df) df[setdiff(names(df), "sex")]
  for (extract in list(as.data.frame, median, function(fit) quantile(fit, probs = c(0.25, 0.5)))) {
    a <- extract(one)
    b <- extract(two)
    expect_identical(names(a), names(without_groups(b)))
    expect_identical(lapply(a, class), lapply(without_groups(b), class))
    expect_identical(names(a)[1], "strata")
  }
  expect_identical(unique(as.data.frame(one)$strata), "all")
  expect_identical(unique(as.data.frame(two)$strata), c("sex=1", "sex=2"))
})

test_that("quantile() returns one row per group and probability", {
  fit <- kaplan_meier(Surv(time, status) ~ sex, data = small)
  q <- quantile(fit, probs = c(0.25, 0.5))
  expect_identical(nrow(q), 4L)
  expect_identical(q$prob, c(0.25, 0.5, 0.25, 0.5))
  expect_error(quantile(fit, probs = 2), "between 0 and 1")
})

test_that("invalid input is rejected", {
  expect_error(kaplan_meier(time ~ 1, data = small), "must be a `Surv\\(\\)` response")
  expect_error(
    kaplan_meier(Surv(time, time + 1, type = "interval2") ~ 1, data = small),
    "right-censored or counting-process"
  )
  expect_error(kaplan_meier(Surv(time, status) ~ 1, data = small, conf_level = 1), "between 0 and 1")
  expect_error(kaplan_meier(Surv(time, status) ~ 1, data = small, conf_type = "logit"))
  expect_error(kaplan_meier(Surv(time, status) ~ 1, data = small, weights = -time), "non-negative")
  expect_error(kaplan_meier(Surv(time, status) ~ 1, data = small, robust = NA), "`TRUE` or `FALSE`")
})

test_that("a fit prints a summary per group", {
  expect_snapshot({
    kaplan_meier(Surv(time, status) ~ 1, data = small)
    kaplan_meier(Surv(time, status) ~ sex, data = small)
  })
})

test_that("summary() at given times matches the risk-table fixture", {
  skip_if_no_shared_cases()
  skip_if_not_installed("survival")
  fixture <- read_fixture("risk_table_lung_sex")
  fit <- kaplan_meier(Surv(time, status) ~ sex, data = survival::lung)
  table <- summary(fit, times = r_numbers(fixture$times))
  for (sex in names(fixture$n_risk)) {
    rows <- table[table$sex == as.numeric(sex), ]
    expect_equal(rows$n_risk, r_numbers(fixture$n_risk[[sex]]), label = paste("sex", sex))
  }
})

test_that("summary() counts the events between times and reads the curve", {
  fit <- kaplan_meier(Surv(time, status) ~ 1, data = small)
  curve <- as.data.frame(fit)
  times <- c(500, 0, 300, 2000)
  table <- summary(fit, times = times)
  expect_identical(table$time, sort(times))
  expect_identical(table$n_event, c(0, 3, 4, 1))
  expect_identical(table$n_censor, c(0, 0, 0, 2))
  expect_identical(table$n_risk, c(10, 7, 3, 0))
  expect_identical(sum(table$n_event), sum(curve$n_event))
  expect_identical(table$estimate[1], 1)
  expect_equal(table$estimate[3], curve$estimate[curve$time == 455])
  expect_equal(table$std_error[3], curve$std_error[curve$time == 455])
})

test_that("predict() reads the survival and cumulative hazard step functions", {
  fit <- kaplan_meier(Surv(time, status) ~ sex, data = small)
  curve <- as.data.frame(fit)
  pred <- predict(fit, times = c(100, 306, 400))
  expect_named(pred, c("strata", "sex", "time", "estimate"))
  first <- curve[curve$sex == 1, ]
  expect_identical(pred$estimate[pred$sex == 1], c(1, first$estimate[first$time == 306], first$estimate[first$time == 306]))

  cumhaz <- predict(fit, times = c(0, 1e4), what = "cumhaz")
  na <- as.data.frame(nelson_aalen(Surv(time, status) ~ sex, data = small))
  expect_identical(cumhaz$estimate[c(1, 3)], c(0, 0))
  expect_equal(cumhaz$estimate[2], max(na$estimate[na$sex == 1]))
  expect_error(predict(fit, times = "a"), "one or more numbers")
})

test_that("rmst() matches the fixture on lung and veteran", {
  skip_if_no_shared_cases()
  skip_if_not_installed("survival")
  fixture <- read_fixture("rmst")
  lung <- rmst(kaplan_meier(Surv(time, status) ~ 1, data = survival::lung), tau = fixture$lung$tau)
  expect_equal(lung$estimate, fixture$lung$rmst, tolerance = TOL)
  expect_equal(lung$std_error, fixture$lung$se, tolerance = TOL)
  veteran <- rmst(
    kaplan_meier(Surv(time, status) ~ 1, data = survival::veteran),
    tau = fixture$veteran$tau
  )
  expect_equal(veteran$estimate, fixture$veteran$rmst, tolerance = TOL)
  expect_equal(veteran$std_error, fixture$veteran$se, tolerance = TOL)
  expect_equal(veteran$conf_high - veteran$estimate, qnorm(0.975) * veteran$std_error)
})

test_that("rmst() is the area under the step function", {
  fit <- kaplan_meier(Surv(time, status) ~ 1, data = small)
  curve <- as.data.frame(fit)
  grid <- seq(0, 400, by = 0.01)
  area <- sum(predict(fit, times = grid[-length(grid)])$estimate) * 0.01
  expect_equal(rmst(fit, tau = 400)$estimate, area, tolerance = 1e-6)
  # Past the last time the curve stays at its last value.
  expect_equal(
    rmst(fit, tau = 1100)$estimate - rmst(fit, tau = 1050)$estimate,
    50 * curve$estimate[nrow(curve)]
  )
})

test_that("rmrl() is the conditional restricted mean", {
  fit <- kaplan_meier(Surv(time, status) ~ sex, data = small)
  at_zero <- rmrl(fit, s = 0, tau = 600)
  expect_equal(at_zero[c("estimate", "std_error")], rmst(fit, tau = 600)[c("estimate", "std_error")])

  s <- 250
  result <- rmrl(fit, s = s, tau = 600)
  expect_named(result, c("strata", "sex", "s", "tau", "estimate", "std_error", "conf_low", "conf_high"))
  survival_at_s <- predict(fit, times = s)$estimate
  expected <- (rmst(fit, tau = 600)$estimate - rmst(fit, tau = s)$estimate) / survival_at_s
  expect_equal(result$estimate, expected)

  expect_error(rmrl(fit, s = 600, tau = 600), "greater than `s`")
  expect_error(rmrl(fit, s = -1, tau = 600), "no less than 0")
  expect_true(is.na(rmrl(kaplan_meier(Surv(time, status) ~ 1, data = small[-c(3, 6), ]), s = 900, tau = 1000)$estimate))
})
